local parent
local success = pcall(function()
    parent = game:GetService("CoreGui")
end)

if not success or not parent then
    local player = game:GetService("Players").LocalPlayer
    if player then
        parent = player:WaitForChild("PlayerGui")
    end
end

if parent then
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "BeautifulLoadingScreen"
    screenGui.IgnoreGuiInset = true
    screenGui.DisplayOrder = 999999999
    screenGui.ResetOnSpawn = false

    local background = Instance.new("Frame")
    background.Name = "BlackBackground"
    background.Size = UDim2.new(1, 0, 1, 0)
    background.BackgroundColor3 = Color3.fromRGB(10, 10, 12)
    background.BorderSizePixel = 0
    background.Parent = screenGui

    local textContainer = Instance.new("Frame")
    textContainer.Size = UDim2.new(0.8, 0, 0.3, 0)
    textContainer.Position = UDim2.new(0.1, 0, 0.35, 0)
    textContainer.BackgroundTransparency = 1
    textContainer.Parent = background

    local textLabel = Instance.new("TextLabel")
    textLabel.Name = "LoadingText"
    textLabel.Size = UDim2.new(1, 0, 1, 0)
    textLabel.BackgroundTransparency = 1
    textLabel.Font = Enum.Font.GothamBlack
    textLabel.Text = "It hasn't crashed,\nthe script takes about 30 seconds to load,\ndon't restart."
    textLabel.TextColor3 = Color3.fromRGB(255, 120, 200)
    textLabel.TextScaled = true
    textLabel.Parent = textContainer

    local textConstraint = Instance.new("UITextSizeConstraint")
    textConstraint.MaxTextSize = 65
    textConstraint.Parent = textLabel

    local uiGradient = Instance.new("UIGradient")
    uiGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 120, 200)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 160, 220)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 120, 200))
    })
    uiGradient.Parent = textLabel

    local uiStroke = Instance.new("UIStroke")
    uiStroke.Color = Color3.fromRGB(255, 255, 255)
    uiStroke.Thickness = 2.5
    uiStroke.LineJoinMode = Enum.LineJoinMode.Round
    uiStroke.Parent = textLabel

    local glowLabel = textLabel:Clone()
    glowLabel.Name = "Glow"
    glowLabel.ZIndex = textLabel.ZIndex - 1
    glowLabel.TextColor3 = Color3.fromRGB(255, 120, 200)
    glowLabel.TextTransparency = 0.5
    glowLabel.Parent = textContainer

    glowLabel:ClearAllChildren()
    local glowStroke = Instance.new("UIStroke")
    glowStroke.Color = Color3.fromRGB(255, 120, 200)
    glowStroke.Thickness = 5
    glowStroke.Transparency = 0.7
    glowStroke.Parent = glowLabel

    local glowConstraint = Instance.new("UITextSizeConstraint")
    glowConstraint.MaxTextSize = 65
    glowConstraint.Parent = glowLabel

    screenGui.Parent = parent

    task.delay(10, function()
        if screenGui and screenGui.Parent then
            local ts = game:GetService("TweenService")
            local tweenInfo = TweenInfo.new(1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
            
            ts:Create(background, tweenInfo, {BackgroundTransparency = 1}):Play()
            ts:Create(textLabel, tweenInfo, {TextTransparency = 1}):Play()
            ts:Create(uiStroke, tweenInfo, {Transparency = 1}):Play()
            ts:Create(glowLabel, tweenInfo, {TextTransparency = 1}):Play()
            ts:Create(glowStroke, tweenInfo, {Transparency = 1}):Play()

            task.wait(1)
            screenGui:Destroy()
        end
    end)
end

wait(5)

